def _compute_validity_date(self):
    today = fields.Date.context_today(self)
    for order in self:
        days = order.company_id.quotation_validity_days
        if days > 0:
            order.validity_date = today + timedelta(days)
        else:
            order.validity_date = False

def _unlink_except_draft_or_cancel(self):
    for order in self:
        if order.state not in ("draft", "cancel"):
            raise UserError(
                order.env._(
                    "You can not delete a sent quotation or a confirmed sales order."
                    " You must first cancel it."
                )
            )

def action_draft(self):
    orders = self.filtered(lambda s: s.state in ["cancel", "sent"])
    return orders.write({
        "state": "draft",
        "signature": False,
        "signed_by": False,
        "signed_on": False,
    })

def _get_confirmation_template(self):
    """Get the mail template sent on SO confirmation (or for confirmed SO's).

    :return: `mail.template` record or None if default template wasn't found
    """
    self.ensure_one()
    default_confirmation_template_id = (
        self.env["ir.config_parameter"].sudo().get_int("sale.default_confirmation_template")
    )
    default_confirmation_template = (
        self.env["mail.template"].browse(default_confirmation_template_id).exists()
    )
    if default_confirmation_template:
        return default_confirmation_template
    return self.env.ref("sale.mail_template_sale_confirmation", raise_if_not_found=False)

def _confirmation_error_message(self):
    """Return whether order can be confirmed or not if not then return error message."""
    self.ensure_one()
    if self.state not in {"draft", "sent"}:
        return self.env._("Some orders are not in a state requiring confirmation.")

    return False

def action_cancel(self):
    """Cancel sales order and related draft invoices."""
    if any(order.locked for order in self):
        raise UserError(self.env._("You cannot cancel a locked order. Please unlock it first."))
    return self._action_cancel()

def _action_cancel(self):
    inv = self.invoice_ids.filtered(lambda inv: inv.state == "draft")
    inv.button_cancel()
    return self.write({"state": "cancel"})

def _get_portal_return_action(self):
    """Return the action used to display orders when returning from customer portal."""
    self.ensure_one()
    return self.env.ref("sale.action_quotations_with_onboarding")

def _unlink_if_cancelled(self):
    for order in self:
        if not order.state == 'cancel':
            raise UserError(_('In order to delete a purchase order, you must cancel it first.'))

def button_draft(self):
    self.write({'state': 'draft'})
    return {}

def button_confirm(self):
    for order in self:
        if order.state not in ['draft', 'sent']:
            continue
        error_msg = order._confirmation_error_message()
        if error_msg:
            raise UserError(error_msg)
        order.order_line._validate_analytic_distribution()
        # Deal with double validation process
        if order._approval_allowed():
            order.button_approve()
        else:
            order.write({'state': 'to approve'})
    return True

def button_cancel(self):
    locked_purchase_orders = self.filtered(lambda po: po.locked)
    if locked_purchase_orders:
        raise UserError(self.env._("Unable to cancel purchase order(s): %s. You must first unlock them.", locked_purchase_orders.mapped('display_name')))

    purchase_orders_with_invoices = self.filtered(lambda po: any(i.state not in ('cancel', 'draft') for i in po.invoice_ids))
    if purchase_orders_with_invoices:
        raise UserError(_("Unable to cancel purchase order(s): %s. You must first cancel their related vendor bills.", purchase_orders_with_invoices.mapped('display_name')))
    self.write({'state': 'cancel'})

def _confirmation_error_message(self):
    """ Return whether order can be confirmed or not if not then return error message. """
    self.ensure_one()
    if any(
        not line.display_type
        and not line.is_downpayment
        and not line.product_id
        for line in self.order_line
    ):
        return _("Some order lines are missing a product, you need to correct them before going further.")

    return False

def get_confirm_url(self, confirm_type=None):
    """Create url for confirm reminder or purchase reception email for sending
    in mail. Unsuported anymore. We only use the acknowledge mechanism. Keep it
    for backward compatibility"""
    if confirm_type in ['reminder', 'reception', 'decline']:
        return self.get_acknowledge_url()
    return self.get_portal_url()

def _compute_return_count(self):
    for picking in self:
        picking.return_count = len(picking.return_ids)

def _compute_validate_button_style(self):
    for picking in self:
        if picking.state in ('done', 'cancel'):
            picking.validate_button_style = 'invisible'
        elif picking.state in ('waiting', 'assigned'):
            picking.validate_button_style = 'primary'
        else:
            picking.validate_button_style = 'secondary'

def action_confirm(self):
    self._check_company()
    if not self.env.context.get('skip_zero_demand_check') and not modules.module.current_test:
        # Check for zero demand moves before confirming
        zero_demand_moves = self.move_ids.filtered(lambda m: m.product_uom_qty <= 0)
        if zero_demand_moves:
            return self._action_generate_zero_demand_wizard()

    # call `_action_confirm` on every draft move
    self.move_ids.filtered(lambda move: move.state == 'draft')._action_confirm()

    # run scheduler for moves forecasted to not have enough in stock
    self.move_ids.filtered(lambda move: move.state not in ('draft', 'cancel', 'done'))._trigger_scheduler()

    if self.env.user.has_group('stock.group_stock_picking_batch'):
        for picking in self:
            picking._find_auto_batch()
    return True

def action_cancel(self):
    self.move_ids._action_cancel()
    self.write({'is_locked': True})
    self.filtered(lambda x: not x.move_ids).state = 'cancel'
    # Remove the cancelled operation from its batch if the batch has other active picking(s).
    for picking in self:
        if picking.batch_id and any(picking.state != 'cancel' for picking in picking.batch_id.picking_ids):
            picking.batch_id = None
    return True

def action_return(self):
    new_picking = self._create_return()
    return {
        'name': _('Returned Picking'),
        'type': 'ir.actions.act_window',
        'res_model': 'stock.picking',
        'res_id': new_picking.id,
        'view_mode': 'form',
        'context': self.env.context,
    }

def action_return_all(self):
    """ Set all the quantities in the return picking as the original picking's done quantities
    """
    self.ensure_one()
    if self.return_id:
        for return_move in self.move_ids.filtered(lambda m: m.state not in ('done', 'cancel')):
            orig_move = return_move.origin_returned_move_id
            quantity = orig_move.quantity
            for dest_move in orig_move.move_dest_ids - return_move:
                if not dest_move.origin_returned_move_id or dest_move.origin_returned_move_id != orig_move:
                    continue
                quantity -= dest_move.quantity
            quantity = return_move.uom_id.round(quantity)
            return_move.product_uom_qty = quantity

def action_clear_return(self):
    self.ensure_one()
    if self.return_id:
        self.move_ids.product_uom_qty = 0

def _send_confirmation_email(self):
    subtype_id = self.env['ir.model.data']._xmlid_to_res_id('mail.mt_comment')
    for stock_pick in self.filtered(lambda p: p.company_id.stock_move_email_validation and p.picking_type_id.code == 'outgoing'):
        delivery_template = stock_pick.company_id.stock_mail_confirmation_template_id
        stock_pick.with_context(force_send=True).message_post_with_source(
            delivery_template,
            email_layout_xmlid='mail.mail_notification_light',
            subtype_id=subtype_id,
        )

def button_validate(self):
    self = self.filtered(lambda p: p.state != 'done')
    draft_picking = self.filtered(lambda p: p.state == 'draft')
    res = draft_picking.with_context(to_validate=True).action_confirm()
    if res is not True:
        return res
    for move in draft_picking.move_ids:
        if move.uom_id.is_zero(move.quantity) and not move.uom_id.is_zero(move.product_uom_qty):
            move.quantity = move.product_uom_qty

    # Sanity checks.
    if not self.env.context.get('skip_sanity_check', False):
        self._sanity_check()

    # Run the pre-validation wizards. Processing a pre-validation wizard should work on the
    # moves and/or the context and never call `_action_done`.
    if not self.env.context.get('button_validate_picking_ids'):
        self = self.with_context(button_validate_picking_ids=self.ids)
    res = self._pre_action_done_hook()
    if res is not True:
        return res

    # Call `_action_done`.
    pickings_not_to_backorder = self.filtered(lambda p: p.picking_type_id.create_backorder == 'never')
    if self.env.context.get('picking_ids_not_to_backorder'):
        pickings_not_to_backorder |= self.browse(self.env.context['picking_ids_not_to_backorder']).filtered(
            lambda p: p.picking_type_id.create_backorder != 'always'
        )
    pickings_to_backorder = self - pickings_not_to_backorder
    if pickings_not_to_backorder:
        pickings_not_to_backorder.with_context(cancel_backorder=True)._action_done()
    if pickings_to_backorder:
        pickings_to_backorder.with_context(cancel_backorder=False)._action_done()

    # Remove done pickings from their batch.
    if any(picking.state == 'done' for picking in self):
        to_assign_ids = set()
        if self and self.env.context.get('pickings_to_detach'):
            pickings_to_detach = self.env['stock.picking'].browse(self.env.context['pickings_to_detach'])
            pickings_to_detach.batch_id = False
            pickings_to_detach.move_ids.filtered(lambda m: not m.quantity).picked = False
            to_assign_ids.update(self.env.context['pickings_to_detach'])

        for picking in self:
            if picking.state != 'done':
                continue
            # Avoid inconsistencies in states of the same batch when validating a single picking in a batch.
            if picking.batch_id and any(p.state != 'done' for p in picking.batch_id.picking_ids):
                picking.batch_id = None
            # If backorder were made and auto-batch is enabled, seek a batch for each of them with the selected criterias.
            to_assign_ids.update(picking.backorder_ids.ids)

        # If batch setting is enabled, auto-batch done pickings' backorders.
        if self.env.user.has_group('stock.group_stock_picking_batch'):
            # To avoid inconsistencies, all incorrect pickings must be removed before assigning backorder pickings
            assignable_pickings = self.env['stock.picking'].browse(to_assign_ids)
            for picking in assignable_pickings:
                picking._find_auto_batch()
            assignable_pickings.move_line_ids.with_context(skip_auto_waveable=True)._auto_wave()

    report_actions = self._get_autoprint_report_actions()
    if report_actions:
        return {
            'type': 'ir.actions.client',
            'tag': 'do_multi_print',
            'params': {
                'reports': report_actions,
            }
        }
    return True

def action_split_transfer(self):
    if self.state == 'done':
        return
    if all(m.uom_id.is_zero(m.quantity) for m in self.move_ids):
        raise UserError(_("%s: Nothing to split. Fill the quantities you want in a new transfer in the done quantities", self.display_name))
    if all(m.uom_id.compare(m.quantity, m.product_uom_qty) == 0 for m in self.move_ids):
        raise UserError(_("%s: Nothing to split, all demand is done. For split you need at least one line not fully fulfilled", self.display_name))
    if any(m.uom_id.compare(m.quantity, m.product_uom_qty) > 0 for m in self.move_ids):
        raise UserError(_("%s: Can't split: quantities done can't be above demand", self.display_name))

    moves = self.move_ids.filtered(lambda m: m.state not in ('done', 'cancel') and m.quantity != 0)
    backorder_moves = moves._create_backorder()
    backorder_moves += self.move_ids.filtered(lambda m: m.quantity == 0)
    backorder = self._create_backorder(backorder_moves=backorder_moves, from_manual_backorder=True)
    backorder.message_post(
        body=self.env._('Split from %(original_picking_link)s.', original_picking_link=self._get_html_link())
    )
    return {
        'name': self.env._('Split Backorder'),
        'type': 'ir.actions.act_window',
        'res_model': 'stock.picking',
        'view_mode': 'form',
        'res_id': backorder.id,
    }

def _autoconfirm_picking(self):
    """ Automatically run `action_confirm` on `self` if one of the
    picking's move was added after the initial
    call to `action_confirm`. Note that `action_confirm` will only work on draft moves.
    """
    for picking in self:
        if picking.state in ('done', 'cancel'):
            continue
        if not picking.move_ids:
            continue
        if any(move.additional for move in picking.move_ids):
            picking.with_context(skip_zero_demand_check=True).action_confirm()
    to_confirm = self.move_ids.filtered(lambda m: m.state == 'draft' and m.quantity)
    to_confirm._action_confirm()

def action_see_returns(self):
    self.ensure_one()
    if len(self.return_ids) == 1:
        return {
            "type": "ir.actions.act_window",
            "res_model": "stock.picking",
            "views": [[False, "form"]],
            "res_id": self.return_ids.id
        }
    return {
        'name': _('Returns'),
        "type": "ir.actions.act_window",
        "res_model": "stock.picking",
        "views": [[False, "list"], [False, "form"]],
        "domain": [('id', 'in', self.return_ids.ids)],
    }

def _add_to_wave_post_picking_split_hook(self):
    # Hook meant to be overriden
    pass

def get_shipments_returns(model_name):
    "Computes the returns or shipments"
    def method(self, name):
        pool = Pool()
        Model = pool.get(model_name)
        field = getattr(self.__class__, name)
        order = field.order if field.order is not None else Model._order
        shipments = set()
        for line in self.line_lines:
            for move in line.moves:
                if isinstance(move.shipment, Model):
                    shipments.add(move.shipment)
        return sort(shipments, order)
    return method

def search_shipments_returns(model_name):
    "Search on shipments or returns"
    def method(self, name, clause):
        _, operator, operand, *extra = clause
        nested = clause[0][len(name):]
        if not nested:
            if isinstance(clause[2], str):
                nested = '.rec_name'
            else:
                nested = '.id'
        return [('lines.moves.shipment' + nested,
                operator, operand, model_name, *extra)]
    return classmethod(method)

def validate_fields(cls, sales, field_names):
    super().validate_fields(sales, field_names)
    cls.check_method(sales, field_names)

def draft(cls, sales):
    cls.write(sales, {
            'tax_amount_cache': None,
            'untaxed_amount_cache': None,
            'total_amount_cache': None,
            })

def _move_remaining_quantity(self):
    "Compute the remaining quantity to ship"
    pool = Pool()
    Uom = pool.get('product.uom')
    if self.type != 'line' or not self.product:
        return
    if not self.movable:
        return
    skips = set(self.moves_ignored)
    quantity = abs(self.quantity)
    if self.sale.shipment_method == 'invoice':
        invoices_ignored = set(self.sale.invoices_ignored)
        for invoice_line in self.invoice_lines:
            if invoice_line.type != 'line':
                continue
            if invoice_line.invoice in invoices_ignored:
                quantity -= Uom.compute_qty(
                    invoice_line.unit or self.unit, invoice_line.quantity,
                    self.unit)
    for move in self.moves:
        if move.state == 'done' or move in skips:
            quantity -= Uom.compute_qty(
                move.unit, move.quantity, self.unit)
    return quantity

def do_return_(self, action):
    sales = self.records
    return_sales = self.model.copy(sales, default={
            'origin': lambda data: (
                '%s,%s' % (self.model.__name__, data['id'])),
            'lines.quantity': lambda data: (
                data['quantity'] * -1 if data['type'] == 'line'
                else data['quantity']),
            })

    data = {'res_id': [s.id for s in return_sales]}
    if len(return_sales) == 1:
        action['views'].reverse()
    return action, data

def __setup__(cls):
    super().__setup__()
    t = cls.__table__()
    cls._sql_indexes.add(
        Index(
            t,
            (t.state, Index.Equality(cardinality='low')),
            where=t.state == 'draft'))
    cls._order = [
        ('date', 'DESC'),
        ('id', 'DESC'),
        ]
    cls._transitions |= {
        ('draft', 'validated'),
        }
    cls._buttons.update({
            'validate_amendment': {
                'invisible': Eval('state') != 'draft',
                'depends': ['state'],
                },
            })

def _stock_moves(cls, line):
    for move in line.moves:
        if move.state in {'staging', 'draft'}:
            yield move

def on_change_with_state(self, name=None):
    if self.amendment:
        return self.amendment.state

def on_change_line(self):
    if self.line:
        self.product = self.line.product
        self.quantity = self.line.quantity
        self.unit = self.line.unit
        self.unit_price = self.line.unit_price
        self.description = self.line.description
    else:
        self.product = self.quantity = self.unit = self.unit_price = None
        self.description = None

def on_change_party(self):
    if not self.invoice_party:
        self.invoice_address = None
    if not self.shipment_party:
        self.shipment_address = None
    if self.party:
        if not self.invoice_address:
            self.invoice_address = self.party.address_get(type='invoice')
        if not self.shipment_address:
            with Transaction().set_context(
                    warehouse=(
                        self.warehouse.id if self.warehouse else None)):
                self.shipment_address = self.party.address_get(
                    type='delivery')

def on_change_invoice_party(self):
    if self.invoice_party:
        self.invoice_address = self.invoice_party.address_get(
            type='invoice')
    elif self.party:
        self.invoice_address = self.party.address_get(type='invoice')

def on_change_shipment_party(self):
    with Transaction().set_context(
            warehouse=self.warehouse.id if self.warehouse else None):
        if self.shipment_party:
            self.shipment_address = self.shipment_party.address_get(
                type='delivery')
        elif self.party:
            self.shipment_address = self.party.address_get(type='delivery')

def on_change_with_product_uom_category(self, name=None):
    if self.line:
        if self.line.product_uom_category:
            return self.line.product_uom_category
        elif self.line.unit:
            return self.line.unit.category

def apply(self, sale):
    assert self.sale == sale
    sale_line = None
    if self.line:
        for line in sale.lines:
            if self.line == line:
                sale_line = line
                break
    getattr(self, '_apply_%s' % self.action)(sale, sale_line)

def _apply_taxes(self, sale, sale_line):
    for line in sale.lines:
        if line.product:
            line.taxes = line.compute_taxes(sale.party)

def cancel(cls, shipments):
    Move = Pool().get('stock.move')
    Move.cancel([m for s in shipments
            for m in s.incoming_moves + s.inventory_moves])

def draft(cls, shipments):
    Move = Pool().get('stock.move')
    Move.draft([m for s in shipments for m in s.incoming_moves
            if m.state != 'staging'])
    Move.delete([m for s in shipments for m in s.inventory_moves
            if m.state in {'staging', 'draft', 'cancelled'}])

def on_change_supplier(self):
    if self.supplier:
        self.delivery_address = self.supplier.address_get('delivery')
        self.to_location = self.supplier.supplier_location

def _set_move_planned_date(cls, shipments):
    '''
    Set planned date of moves for the shipments
    '''
    Move = Pool().get('stock.move')
    to_write = []
    for shipment in shipments:
        moves = [m for m in shipment.moves
                if (m.state not in {'done', 'cancelled'}
                    and m.planned_date != shipment._move_planned_date)]
        if moves:
            to_write.extend((moves, {
                        'planned_date': shipment._move_planned_date,
                        }))
    if to_write:
        Move.write(*to_write)

def get_origins(self, name):
    return ', '.join(set(filter(None,
                (m.origin_name for m in self.moves))))

def chat_language(self, audience='internal'):
    language = super().chat_language(audience=audience)
    if audience == 'public':
        language = self.supplier.lang.code if self.supplier.lang else None
    return language

def copy(cls, shipments, default=None):
    if default is None:
        default = {}
    else:
        default = default.copy()
    default.setdefault('moves.origin', None)
    default.setdefault('assigned_by', None)
    default.setdefault('done_by', None)
    return super().copy(shipments, default=default)

def draft(cls, shipments):
    Move = Pool().get('stock.move')
    Move.draft([m for s in shipments for m in s.moves
            if m.state != 'staging'])
    for shipment in shipments:
        Move.write([m for m in shipment.moves
                if m.state != 'done'], {
                'from_location': shipment.from_location.id,
                'to_location': shipment.to_location.id,
                'planned_date': shipment.planned_date,
                })

def assign(cls, shipments):
    Move = Pool().get('stock.move')
    Move.assign([m for s in shipments for m in s.assign_moves])

def do(cls, shipments):
    pool = Pool()
    Move = pool.get('stock.move')
    Date = pool.get('ir.date')

    Move.do([m for s in shipments for m in s.moves])
    for company, c_shipments in groupby(
            shipments, key=lambda s: s.company):
        with Transaction().set_context(company=company.id):
            today = Date.today()
        cls.write([s for s in c_shipments if not s.effective_date], {
                'effective_date': today,
                })

def cancel(cls, shipments):
    Move = Pool().get('stock.move')
    Move.cancel([m for s in shipments for m in s.moves])

def assign_try(cls, shipments, with_childs=None):
    pool = Pool()
    Move = pool.get('stock.move')
    shipments = [s for s in shipments if s.state == 'waiting']
    to_assign = defaultdict(list)
    for shipment in shipments:
        location_type = shipment.from_location.type
        for move in shipment.assign_moves:
            if move.assignation_required:
                to_assign[location_type].append(move)
    success = True
    for location_type, moves in to_assign.items():
        if with_childs is None:
            _with_childs = location_type == 'view'
        elif not with_childs and location_type == 'view':
            _with_childs = True
        else:
            _with_childs = with_childs
        if not Move.assign_try(moves, with_childs=_with_childs):
            success = False
    if success:
        cls.assign(shipments)
    else:
        with cls.bulk_func('assign', auto=False) as assign:
            for shipment in shipments:
                if any(
                        m.state in {'staging', 'draft'}
                        for m in shipment.assign_moves
                        if m.assignation_required):
                    continue
                assign.push(shipment)

def _get_reschedule_domain(cls, date):
    return [
        ('state', 'in', ['waiting', 'assigned']),
        ('planned_date', '<', date),
        ]

def draft(cls, shipments):
    Move = Pool().get('stock.move')
    Move.draft([m for s in shipments for m in s.outgoing_moves
            if m.state != 'staging'])
    Move.delete([m for s in shipments for m in s.inventory_moves
            if m.state in {'staging', 'draft', 'cancelled'}])

def cancel(cls, shipments):
    Move = Pool().get('stock.move')
    Move.cancel([m for s in shipments
            for m in s.outgoing_moves + s.inventory_moves])

def __setup__(cls):
    super().__setup__()
    t = cls.__table__()
    cls._sql_indexes.update({
            Index(
                t,
                (t.state, Index.Equality(cardinality='low')),
                where=t.state.in_(['draft', 'received'])),
            })
    cls._transitions |= set((
            ('draft', 'received'),
            ('received', 'done'),
            ('received', 'draft'),
            ('draft', 'cancelled'),
            ('received', 'cancelled'),
            ('cancelled', 'draft'),
            ('done', 'cancelled'),
            ))
    cls._buttons.update({
            'cancel': {
                'invisible': (
                    (Eval('state') == 'cancelled')
                    | ((Eval('state') == 'done')
                        & ~Id('stock',
                            'group_stock_cancellation').in_(
